function cleanText(value) {
    if (value == null) return '';

    return String(value)
        .replace(/\r\n?/g, '\n')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/p>|<\/li>|<\/div>|<\/tr>/gi, '\n')
        .replace(/<[^>]*>/g, ' ')
        .replace(/\[~[^\]]+\]/g, '')
        .replace(/\{code(?::[^}]*)?\}/gi, '')
        .replace(/\{color(?::[^}]*)?\}/gi, '')
        .replace(/\{noformat\}/gi, '')
        .replace(/\u00a0/g, ' ')        
        .replace(/\n[ \t]*\n[ \t]*\n+/g, '\n\n')
        .split('\n')
        .map(line => line.replace(/[ \t]+$/g, ''))
        .join('\n')
        .trim();
}

function pick(obj, ...keys) {
    for (const key of keys) {
        const value = obj[key];

        if (
            value !== undefined &&
            value !== null &&
            String(value).trim() !== ''
        ) {
            return value;
        }
    }

    return '';
}

function parseNumber(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : 0;
}

function normalizeComments(row) {    
    if (Array.isArray(row.Comments)) {
        return row.Comments
            .map((comment, index) => {
                if (comment && typeof comment === 'object') {
                    return {
                        index: Number(comment.index ?? comment.comment_index ?? index) || index,
                        text: cleanText(comment.text ?? comment.content ?? ''),
                        author: cleanText(comment.author ?? comment.username ?? ''),
                        created_at: comment.created_at ?? comment.createdAt ?? ''
                    };
                }

                return {
                    index,
                    text: cleanText(comment),
                    author: '',
                    created_at: ''
                };
            })
            .filter(comment => comment.text);
    }

}

function normalizeAttachments(row) {
    let raw = pick(row, 'Unified_Attachment_Context');

    if (Array.isArray(raw)) {
        return raw
            .map((attachment, index) => {
                const source = cleanText(
                    attachment?.source ??
                    attachment?.filename ??
                    attachment?.name ??
                    ''
                );

                const type = cleanText(
                    attachment?.type ?? 'Unknown'
                );

                const mimeType = cleanText(
                    attachment?.mime_type ?? attachment?.mimeType ?? ''
                );

                const extractor = cleanText(
                    attachment?.extractor ?? attachment?.extraction_method ?? 'unknown'
                );

                const content = cleanText(
                    attachment?.content ?? attachment?.text ?? ''
                );

                return {
                    attachment_id: Number(attachment?.attachment_id) || index + 1,
                    name: source,
                    type,
                    mime_type: mimeType,
                    extractor,
                    content,
                };
            })
            .filter(attachment => attachment.content);
    }

    return [];
}

const row = $input.first().json;

const issueId = String(
    pick(row, 'IssueId', 'Issue id', 'issue_id')
).trim();

if (!issueId) {
    throw new Error('IssueId is missing');
}

const summary = cleanText(pick(row, 'Summary', 'summary'));
const description = cleanText(pick(row, 'Description', 'description'));
const votes = parseNumber(pick(row, 'Votes', 'votes'));

const comments = normalizeComments(row);
const attachments = normalizeAttachments(row);

return [{
    json: {
        issue_id: issueId,
        summary,
        description,
        votes,
        comments,
        attachments,
        attachment_count: attachments.length,
        comment_count: comments.length,
        source: 'jira',
        document_type: 'jira_issue',
        schema_version: 2,
    },
}];
